<script type="text/babel">
const { useState, useEffect } = React;

const START = [
  { id: 1, title: "Morning walk", done: true },
  { id: 2, title: "Python lesson 4", done: false },
  { id: 3, title: "Call Ammi", done: false },
];

function App() {
  const [tasks, setTasks] = useState(START);
  const [show, setShow] = useState("all");

  function toggle(id) {
    setTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
  }

  const visible = tasks.filter(t =>
    show === "all" ? true : show === "done" ? t.done : !t.done);

  return (
    <div>
      {["all", "active", "done"].map(s =>
        <button key={s} onClick={() => setShow(s)} style={{ fontWeight: show === s ? "bold" : "normal" }}>{s}</button>)}
      <ul>
        {visible.map(t => (
          <li key={t.id} onClick={() => toggle(t.id)} style={{ cursor: "pointer", textDecoration: t.done ? "line-through" : "none" }}>
            {t.title}
          </li>
        ))}
      </ul>
      {visible.length === 0 && <p>Nothing here.</p>}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
</script>

