<script type="text/babel">
const { useState, useEffect } = React;

// A pretend server so this works anywhere. In the live project you use real fetch().
function fakeFetchCourses() {
  return new Promise((resolve, reject) => setTimeout(() => {
    if (Math.random() < 0.2) reject(new Error("Network problem, try again"));
    else resolve([{ id: 1, name: "Python" }, { id: 2, name: "Django" }, { id: 3, name: "React" }]);
  }, 800));
}

function App() {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [reload, setReload] = useState(0);

  useEffect(() => {
    setLoading(true); setError("");
    fakeFetchCourses()
      .then(setCourses)
      .catch(e => setError(e.message))
      .finally(() => setLoading(false));
  }, [reload]);                         // run again when reload changes

  if (loading) return <p>Loading…</p>;
  if (error) return <p style={{ color: "red" }}>{error} <button onClick={() => setReload(reload + 1)}>Retry</button></p>;
  return <ul>{courses.map(c => <li key={c.id}>{c.name}</li>)}</ul>;
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
</script>

