function AddStep({ onAdd }) {
  return <button onClick={() => onAdd(500)}>+500 steps</button>;
}

function Progress({ steps, goal }) {
  const pct = Math.min(100, Math.round(steps / goal * 100));
  return (
    <div>
      <div style={{ background: "#eee", borderRadius: 8, height: 14 }}>
        <div style={{ width: pct + "%", background: "#16a34a", height: 14, borderRadius: 8 }} />
      </div>
      <p>{steps} / {goal} ({pct}%)</p>
    </div>
  );
}

function App() {
  const [steps, setSteps] = useState(0);              // lives in the parent
  return (
    <div>
      <Progress steps={steps} goal={10000} />
      <AddStep onAdd={n => setSteps(steps + n)} />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
</script>

