<script type="text/babel">
const { useState, useEffect } = React;

function load() {
  try { return JSON.parse(localStorage.getItem("notes") || "[]"); } catch (e) { return []; }
}

function NoteForm({ onAdd }) {
  const [text, setText] = useState("");
  return (
    <form onSubmit={e => { e.preventDefault(); if (text.trim()) { onAdd(text.trim()); setText(""); } }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="Write a note" />
      <button>Add</button>
    </form>
  );
}

function Note({ note, onDelete, onPin }) {
  return (
    <li>
      {note.pinned ? "📌 " : ""}{note.text}
      <button onClick={() => onPin(note.id)}>pin</button>
      <button onClick={() => onDelete(note.id)}>x</button>
    </li>
  );
}

function App() {
  const [notes, setNotes] = useState(load);
  const [q, setQ] = useState("");

  useEffect(() => {
    try { localStorage.setItem("notes", JSON.stringify(notes)); } catch (e) {}
  }, [notes]);

  const add = text => setNotes([{ id: Date.now(), text, pinned: false }, ...notes]);
  const remove = id => setNotes(notes.filter(n => n.id !== id));
  const pin = id => setNotes(notes.map(n => n.id === id ? { ...n, pinned: !n.pinned } : n));

  const shown = notes
    .filter(n => n.text.toLowerCase().includes(q.toLowerCase()))
    .sort((a, b) => b.pinned - a.pinned);

  return (
    <div>
      <h2>My notes ({notes.length})</h2>
      <NoteForm onAdd={add} />
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search" />
      <ul>{shown.map(n => <Note key={n.id} note={n} onDelete={remove} onPin={pin} />)}</ul>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
</script>
